-- Owner-vs-agent calibration (docs/superpowers/specs/2026-10-07-agent-calibration-design.md).
-- Raw answers never outlive a round: agent answers are nulled after scoring, owner answers only bump per-option counts.
create table calibration_questions (
  id text primary key,
  bank_version int not null,
  text text not null,
  type text not null check (type in ('single_choice', 'likert_5')),
  options jsonb,
  category text not null,
  prior jsonb not null,
  active boolean not null default true
);
create table calibration_rounds (
  id text primary key,
  agent_id text not null references agents(id),
  bank_version int not null,
  question_ids jsonb not null,
  state text not null check (state in ('CREATED', 'AGENT_ANSWERED', 'OWNER_ANSWERING', 'SCORED', 'EXPIRED')),
  agent_answers jsonb,
  agent_answered_at timestamptz,
  owner_opened_at timestamptz,
  agreement numeric, baseline numeric, lift numeric, passed boolean,
  created_at timestamptz not null default now(),
  scored_at timestamptz
);
create unique index calibration_one_open on calibration_rounds (agent_id) where state in ('CREATED', 'AGENT_ANSWERED', 'OWNER_ANSWERING');
create table calibration_counts (
  question_id text not null references calibration_questions(id),
  option int not null,
  n int not null default 0,
  primary key (question_id, option)
);
create table calibration_seen (
  agent_id text not null references agents(id),
  question_id text not null references calibration_questions(id),
  primary key (agent_id, question_id)
);
alter table agents add column calibrated_until timestamptz;
alter table calibration_questions enable row level security;
alter table calibration_rounds enable row level security;
alter table calibration_counts enable row level security;
alter table calibration_seen enable row level security;

